/* Reuse the campaign Notebook and its real notes key, without running campaign simulation. */
(() => {const overlay=document.getElementById('watch-notebook'),launcher=overlay?.previousElementSibling;if(launcher?.tagName==='BUTTON'){launcher.id='cw-ux108b-notebook';launcher.style.cssText='';launcher.textContent='Notebook';launcher.setAttribute('aria-label','Open Watch notebook');document.getElementById('bridge-tools').appendChild(launcher);}window.CW_NOTEBOOK_SNAPSHOT=()=>{try{return {state:JSON.parse(window.CW_LAB.storage.getItem(window.CW_LAB.keys.player)||'{}')};}catch{return {};}};})();
